function hex(c) {
  const r = Math.round(c.r * 255).toString(16).padStart(2, "0");
  const g = Math.round(c.g * 255).toString(16).padStart(2, "0");
  const b = Math.round(c.b * 255).toString(16).padStart(2, "0");
  return r + g + b;
}

function fillStr(n) {
  try {
    const f = n.fills;
    if (!Array.isArray(f) || f.length === 0) return "";
    const parts = [];
    for (const p of f) {
      if (p.type === "SOLID") parts.push("#" + hex(p.color));
      else if (p.type === "IMAGE") parts.push("IMAGE:" + (p.imageRef || "").slice(0, 12));
      else parts.push(p.type);
    }
    return parts.join(",");
  } catch (e) { return "?"; }
}

function dump(n, depth) {
  const o = { id: n.id, name: n.name, type: n.type, w: Math.round(n.width), h: Math.round(n.height) };
