function dump(n, d){
  let s = "  ".repeat(d) + n.type + " " + n.name + " x=" + Math.round(n.x) + " w=" + Math.round(n.width);
  if (n.layoutMode && n.layoutMode !== "NONE") s += " layout=" + n.layoutMode + " align=" + n.primaryAxisAlignItems + "/" + n.counterAxisAlignItems + " sizing=" + n.layoutSizingHorizontal;
  let out = [s];
  if ("children" in n && d < 3) n.children.forEach(c => out = out.concat(dump(c, d+1)));
  return out;
}
return JSON.stringify({tab: dump(tabInst,0), sf: dump(sfInst,0)}, null, 1);
